<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(404);exit;}
function platformVerificationState(array $c): array{$r=accountQuery('SELECT * FROM idea_company_verification WHERE company_id=?',[$c['id']])->fetch();return $r?:['company_id'=>$c['id'],'state'=>$c['status']==='verified'?'approved':($c['status']==='suspended'?'suspended':'registration_started'),'review_notes'=>'','updated_at'=>0];}
function platformVerificationSet(array $c,string $state,string $notes): void{accountQuery('DELETE FROM idea_company_verification WHERE company_id=?',[$c['id']]);accountQuery('INSERT INTO idea_company_verification(company_id,state,review_notes,updated_at) VALUES(?,?,?,?)',[$c['id'],$state,$notes,platformNow()]);$legacy=$state==='approved'?'verified':($state==='suspended'?'suspended':($state==='rejected'?'rejected':'submitted'));accountQuery('UPDATE idea_companies SET status=? WHERE id=?',[$legacy,$c['id']]);}
function platformDocumentRequirements(): array{return platformConfig()['document_requirements']??['commercial_registration','tax_card'];}
function platformDocuments(string $company): array{return accountQuery('SELECT id,kind,original_name,mime,bytes,scan_status,created_at FROM idea_company_documents WHERE company_id=? ORDER BY created_at DESC',[$company])->fetchAll();}
function platformDocumentUpload(array $u,array $d): array{
 $c=accountCompany($u);$kind=accountString($_POST,'kind',60,true);$allowed=array_unique(array_merge(platformDocumentRequirements(),['commercial_registration','tax_card','vat_certificate','business_address','representative_authorization']));if(!in_array($kind,$allowed,true))accountError(422,'DOCUMENT_KIND_INVALID');
 if((int)($_SERVER['CONTENT_LENGTH']??0)>6291456)accountError(413,'DOCUMENT_TOO_LARGE');$f=$_FILES['document']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>5*1024*1024)accountError(422,'DOCUMENT_UPLOAD_FAILED');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$bytes=file_get_contents($f['tmp_name']);$scan='';
 if(in_array($mime,['image/jpeg','image/png','image/webp'],true)){
  if(!extension_loaded('gd'))accountError(503,'GD_REQUIRED');$info=@getimagesizefromstring($bytes);if(!$info||$info[0]*$info[1]>20000000)accountError(422,'INVALID_IMAGE');$image=@imagecreatefromstring($bytes);if(!$image)accountError(422,'INVALID_IMAGE');ob_start();imagejpeg($image,null,94);$bytes=ob_get_clean();imagedestroy($image);$mime='image/jpeg';$scan='raster_sanitized';
 }elseif($mime==='application/pdf'){
  if(!str_starts_with($bytes,'%PDF-')||preg_match('#/(?:JavaScript|JS|Launch|EmbeddedFile|OpenAction|RichMedia|XFA)\b#i',$bytes))accountError(422,'ACTIVE_DOCUMENT_REJECTED');$scanner=platformConfig()['document_scanner']??[];if(!is_array($scanner)||!count($scanner)||!is_file($scanner[0]))accountError(503,'PDF_SCANNER_REQUIRED');
  $command=array_merge($scanner,[$f['tmp_name']]);$process=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);if(!is_resource($process))accountError(503,'SCANNER_UNAVAILABLE');fclose($pipes[0]);$scanOutput=stream_get_contents($pipes[1]);$scanError=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);if(str_contains($scanError,'database is older'))accountError(503,'PDF_SCANNER_DATABASE_STALE');if($exit!==0)accountError(422,'DOCUMENT_SCAN_REJECTED');$scan='antivirus_clean';
 }else accountError(422,'DOCUMENT_FORMAT_INVALID');
 $id=platformId();$storage=bin2hex(random_bytes(32));$dir=platformPrivateRoot().'/documents';if(!is_dir($dir))mkdir($dir,0700,true);$path=$dir.'/'.$storage;if(file_put_contents($path,$bytes,LOCK_EX)===false)accountError(503,'STORAGE_UNAVAILABLE');chmod($path,0600);
 try{platformTransaction(function()use($c,$u,$kind,$f,$mime,$bytes,$scan,$storage,$id){accountQuery('INSERT INTO idea_company_documents(id,company_id,kind,original_name,mime,bytes,sha256,storage_key,scan_status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$c['id'],$kind,mb_substr(basename($f['name']),0,180),$mime,strlen($bytes),hash('sha256',$bytes),$storage,$scan,platformNow()]);platformVerificationSet($c,'documents_submitted','');platformAudit($u,'document-upload',$id);});}catch(Throwable $e){unlink($path);throw $e;}return ['id'=>$id,'scan_status'=>$scan];
}
function platformVerificationCompany(array $u): array{$c=accountCompany($u);$c['business_details']=json_decode($c['business_details'],true)?:[];return $c;}
function platformVerificationAction(string $a,array $d,array $u): array{
 if($a==='company-verification'){$c=platformVerificationCompany($u);return ['company'=>$c,'verification'=>platformVerificationState($c),'documents'=>platformDocuments($c['id']),'requirements'=>platformDocumentRequirements()];}
 if($a==='company-profile-save'){$c=platformVerificationCompany($u);$details=$c['business_details'];foreach(['registered_address','city','governorate','representative_name','representative_position','commercial_registration','tax_number','vat_number','sector'] as $key)$details[$key]=accountString($d,$key,400,in_array($key,['registered_address','city','representative_name','representative_position','commercial_registration','tax_number','sector'],true));$legal=accountString($d,'legal_name',200,true);$trade=accountString($d,'public_name',200,true);platformTransaction(function()use($c,$details,$legal,$trade,$u){accountQuery('UPDATE idea_companies SET legal_name=?,public_name=?,business_details=? WHERE id=?',[$legal,$trade,platformJson($details),$c['id']]);platformVerificationSet($c,'registration_started','Company details changed; submit for review.');platformAudit($u,'company-profile-update',$c['id']);});return ['saved'=>true];}
 if($a==='company-document-upload')return platformDocumentUpload($u,$d);
 if($a==='company-verification-submit'){$c=platformVerificationCompany($u);$kinds=array_column(platformDocuments($c['id']),'kind');if(array_diff(platformDocumentRequirements(),$kinds))accountError(422,'MISSING_DOCUMENTS');$profile=$c['business_details'];foreach(['registered_address','city','representative_name','representative_position','commercial_registration','tax_number','sector'] as $key)if(empty($profile[$key]))accountError(422,'COMPANY_PROFILE_INCOMPLETE');platformTransaction(function()use($c,$u){platformVerificationSet($c,'pending_verification','');platformAudit($u,'verification-submit',$c['id']);platformNotify($u['id'],'verification-submit:'.$c['id'].':'.platformNow(),'IDEA — Verification submitted','Your company documents are pending review.','/business/verification');});return ['state'=>'pending_verification'];}
 if($a==='admin-verifications'){platformAdmin($u);$companies=accountQuery('SELECT * FROM idea_companies ORDER BY created_at DESC')->fetchAll();foreach($companies as &$c){$c['business_details']=json_decode($c['business_details'],true)?:[];$c['verification']=platformVerificationState($c);$c['documents']=platformDocuments($c['id']);}return ['companies'=>$companies];}
 if($a==='admin-verification-decision'){
  platformAdmin($u);$id=accountString($d,'id',32,true);$state=accountString($d,'state',32,true);$notes=accountString($d,'notes',2000);if(!in_array($state,['under_review','approved','rejected','additional_documents_required','suspended'],true))accountError(422,'INVALID_STATE');
  return platformTransaction(function()use($id,$state,$notes,$u){$c=accountQuery('SELECT * FROM idea_companies WHERE id=?'.platformLock(),[$id])->fetch();if(!$c)accountError(404,'COMPANY_NOT_FOUND');$old=platformVerificationState($c)['state'];$allowed=['under_review'=>['pending_verification','additional_documents_required'],'approved'=>['under_review'],'rejected'=>['under_review'],'additional_documents_required'=>['under_review','pending_verification'],'suspended'=>['approved']];if(!in_array($old,$allowed[$state],true))accountError(409,'VERIFICATION_TRANSITION_INVALID');if($state==='approved'&&array_diff(platformDocumentRequirements(),array_column(platformDocuments($id),'kind')))accountError(422,'MISSING_DOCUMENTS');if(in_array($state,['rejected','additional_documents_required','suspended'],true)&&$notes==='')accountError(422,'REVIEW_REASON_REQUIRED');platformVerificationSet($c,$state,$notes);platformAudit($u,'verification-'.$state,$id);platformNotify($c['owner_id'],'verification:'.$id.':'.platformNow(),'IDEA — Company verification update',$state.($notes?' — '.$notes:''),'/business/verification');return ['state'=>$state];});
 }
 accountError(404,'UNKNOWN_ACTION');
}
function platformDownloadDocument(array $u,string $id): never{
 $r=accountQuery('SELECT d.*,c.owner_id FROM idea_company_documents d JOIN idea_companies c ON c.id=d.company_id WHERE d.id=?',[$id])->fetch();if(!$r||($u['role']!=='admin'&&$r['owner_id']!==$u['id']))accountError(404,'DOCUMENT_NOT_FOUND');$path=platformPrivateRoot().'/documents/'.$r['storage_key'];if(!is_file($path))accountError(404,'DOCUMENT_NOT_FOUND');header('Content-Type: '.$r['mime']);header('Content-Security-Policy: sandbox');header('Content-Disposition: attachment; filename="IDEA-document-'.$r['id'].($r['mime']==='application/pdf'?'.pdf':'.jpg').'"');header('Content-Length: '.filesize($path));session_write_close();readfile($path);exit;
}
